  'te.au.intl.title': '国际出差——ATO 合理金额标准',
  'te.au.intl.desc': 'TD 2025/4 仅规定海外差旅的餐费和杂费合理金额。海外住宿必须始终提供完整收据，不适用任何合理金额标准（TD 2025/4，第 37 段）。\n\n各国家被划分为六个成本组之一（见下方表 8）。适用三个薪资区间，与国内差旅相同。\n\n主要规则：\n• 如同一天前往两个或以上国家，采用较高的成本组\n• 未列入表 8 的国家：采用成本组 3\n• 连续 6 晚或以上的海外差旅：必须保留差旅记录（日记）\n• ECA 标准或 APSC 标准（适用于订阅用户）也被认可为合理标准',
  'te.au.intl.source': 'ATO Taxation Determination TD 2025/4——2025–26 纳税年度（2025 年 6 月 25 日发布）',
  'te.au.intl.t0.title': '表 5——海外差旅，薪资 ≤ $148,250（AUD）',
  'te.au.intl.t0.h.0': '成本组',
  'te.au.intl.t0.h.1': '餐费（AUD/天）',
  'te.au.intl.t0.h.2': '杂费（AUD/天）',
  'te.au.intl.t0.h.3': '每日合计（AUD）',
