  /* ── Austria (AT) ── */
  'te.at.dom.title': '国内出差',
  'te.at.dom.desc': '奥地利没有统一的全国每日津贴标准，而是由各行业的集体协议（Kollektivvertrag）规定，不同行业适用不同标准。\n\n根据最常引用的集体协议（Information & Consulting），最低每日津贴为 €18.40，而依据 Austrian Income Tax Act (EStG) 可享受免税待遇的最高金额为每日 €26.40。\n\n“十二分之一规则（one-twelfth rule）”：每日津贴（最高 €26.40）平均分为 12 份。出差时间超过 3 小时后，每满 1 小时（不足 1 小时按 1 小时计算）可获得 1 份津贴；出差时间不超过 3 小时则不享有津贴。\n\n税务说明：根据所得税法，截至 2025 年，每日免税上限为 €30。许多集体协议设定了较低的实际适用上限（例如 €26.40）。超过免税上限的部分需缴纳所得税。\n\n住宿：凭实际住宿发票按实际费用报销；如无发票，可享受 €15 的免税住宿定额津贴。',
  'te.at.dom.source': 'WKO Collective Agreement for Information and Consulting (2025); Austrian Income Tax Act (EStG)',
  'te.at.dom.t0.title': '十二分之一规则——每日津贴计算（最高 €26.40/天）',
  'te.at.dom.t0.h.0': '出差时长',
