  /* ── Bangladesh (BD) ── */
  'te.bd.dom.title': '国内出差',
  'te.bd.dom.desc': '孟加拉国并未为私营部门员工规定法定每日津贴标准。政府根据公务员的薪资等级（BPS 等级制度），为其制定每日津贴（TA/DA — Travel Allowance / Daily Allowance）。\n\n根据 Income Tax Act 2023，私营雇主为真实公务出差支付的差旅津贴通常可免征所得税，前提是金额合理且具备适当文件记录。税务机关可能会参考公共部门标准来评估其“合理性”。\n\n跨国企业的市场惯例：专业人员每日 BDT 1,500–3,000（住宿通常另行报销）。所有国内标准均以孟加拉塔卡（BDT）计。',
  'te.bd.dom.source': 'Income Tax Act 2023; Finance Division — TA/DA Circulars',
  'te.bd.dom.h.0': '等级 / 类别',
  'te.bd.dom.h.1': '每日津贴（BDT/天）',
  'te.bd.dom.h.2': '来源类型',
  'te.bd.dom.r.0.0': '政府——1–5 级（高级官员 / 秘书）',
  'te.bd.dom.r.0.1': '1,500',
  'te.bd.dom.r.0.2': '政府参考标准',
  'te.bd.dom.r.1.0': '政府——6–10 级（中层官员）',
  'te.bd.dom.r.1.1': '1,000',
  'te.bd.dom.r.1.2': '政府参考标准',
  'te.bd.dom.r.2.0': '政府——11–20 级（初级官员及员工）',
  'te.bd.dom.r.2.1': '600',
  'te.bd.dom.r.2.2': '政府参考标准',
  'te.bd.dom.r.3.0': '私营部门——跨国企业市场惯例',
  'te.bd.dom.r.3.1': '1,500 – 3,000',
  'te.bd.dom.r.3.2': '市场惯例',
  'te.bd.intl.title': '国际出差',
  'te.bd.intl.desc': '对于境外出差，Finance Division 为政府官员制定每日津贴标准。标准会因目的地及官员等级而异。私营雇主在法律上无需遵循这些标准，但通常会将其作为参考。\n\n标准以每日美元（USD）计，包含餐费及杂费。住宿费用通常凭收据另行报销。',
  'te.bd.intl.source': 'Finance Division — Foreign Travel TA/DA Rules',
  'te.bd.intl.h.0': '目的地 / 等级',
  'te.bd.intl.h.1': '标准（USD/天）',
  'te.bd.intl.h.2': '来源类型',
  'te.bd.intl.r.0.0': '高成本目的地——高级官员（美国、英国、日本）',
  'te.bd.intl.r.0.1': '250 – 350',
  'te.bd.intl.r.0.2': '政府参考标准',
  'te.bd.intl.r.1.0': '高成本目的地——初级官员',
  'te.bd.intl.r.1.1': '200 – 250',
  'te.bd.intl.r.1.2': '政府参考标准',
  'te.bd.intl.r.2.0': '中等成本目的地——高级官员（欧盟、海湾地区）',
  'te.bd.intl.r.2.1': '180 – 250',
  'te.bd.intl.r.2.2': '政府参考标准',
