  'te.be.dom.r.4.0': '如免费提供餐食——晚餐扣减',
  'te.be.dom.r.4.1': '每日标准的 45%',
  'te.be.dom.r.4.2': '法定',
  'te.be.intl.title': '国际出差',
  'te.be.intl.desc': '比利时将国际出差分为两类：\n\n  • 第 1 类（短期）：连续不超过 30 个日历日的出差。涵盖餐费及小额支出（当地交通、小吃、小费、电话费）。雇主可采用所有国家统一的每日 €37.18 定额标准，或采用下表所列的各国特定标准。\n\n  • 第 2 类（长期）：超过 30 天且最长不超过 24 个月的出差。适用标准略高。如员工永久迁居至该国家，则停止发放津贴。\n\n住宿：不包含在每日津贴内，须另行报销，最高不得超过所列限额。\n\n餐费扣减：如雇主或第三方免费提供午餐，扣减 35%；免费提供晚餐，扣减 45%。\n所有标准均以欧元（EUR）计。来源：Ministerieel besluit 14 July 2025。',
  'te.be.intl.source': 'Ministerieel besluit published BS 14.07.2025 — new rates effective 14 July 2025',
