  /* ── Brazil (BR) ── */
  'te.br.dom.title': '国内出差',
  'te.br.dom.desc': '巴西并未为私营部门雇主规定强制性每日津贴标准。各公司可自行制定标准。\n\n税务处理（CLT Art. 457 §2，2017 年修订）：向员工支付的公务差旅每日津贴（diárias）不被视为工资组成部分，并且可全额免征所得税，金额不设上限。该规定于 2017 年修改；此前将免税每日津贴限制为月薪 50% 的规定已被废除。\n\n重要提示：该免税待遇仅适用于确实用于差旅费用的款项，而不能被设计为变相工资。如支付金额超过实际差旅成本，或与真实差旅无关，税务机关（Receita Federal）可能会将其重新认定为工资。\n\n以下列出联邦公共部门标准（Decreto 12.417/2024）供参考。私营雇主通常将这些标准作为参考基准。',
  'te.br.dom.source': 'CLT Art. 457 §2 (amended 2017) + Art. 470 — Consolidação das Leis do Trabalho',
  'te.br.dom.h.0': '类别',
  'te.br.dom.h.1': '标准（BRL/天）',
  'te.br.dom.h.2': '来源类型',
  'te.br.dom.r.0.0': '联邦公共部门——部长 / 州务秘书',
  'te.br.dom.r.0.1': 'BRL 700.33',
  'te.br.dom.r.0.2': '政府参考标准',
  'te.br.dom.r.1.0': '联邦公共部门——DAS 4–6 / 高级公务员',
  'te.br.dom.r.1.1': 'BRL 508.17',
  'te.br.dom.r.1.2': '政府参考标准',
  'te.br.dom.r.2.0': '联邦公共部门——其他联邦员工',
  'te.br.dom.r.2.1': 'BRL 335.60',
  'te.br.dom.r.2.2': '政府参考标准',
  'te.br.dom.r.3.0': '私营部门',
  'te.br.dom.r.3.1': '依据公司政策（无法定标准）',
  'te.br.dom.r.3.2': '市场惯例',
  'te.br.dom.r.4.0': '税务处理（CLT Art. 457 §2）',
  'te.br.dom.r.4.1': '全额免税且不设上限——仅限真实差旅费用',
  'te.br.dom.r.4.2': '法定',
  'te.br.intl.title': '国际出差',
  'te.br.intl.desc': '巴西联邦公共部门员工的国际差旅每日津贴由 Decreto 12.417/2024 规定。这些属于参考标准，私营雇主在法律上无需遵循，但通常会将其作为参考。\n\n标准以每日美元（USD）计，涵盖餐费及杂费。住宿费用通常凭收据另行报销。\n\n私营部门：国际差旅每日津贴同样适用 CLT Art. 457 §2 的免税规定，只要确实用于公务差旅，即可全额免税且不设上限。',
  'te.br.intl.source': 'Decreto 12.417/2024 — Federal public sector international rates',
  'te.br.intl.h.0': '目的地 / 等级',
  'te.br.intl.h.1': '标准（USD/天）',
  'te.br.intl.h.2': '来源类型',
  'te.br.intl.r.0.0': 'A 组——高成本目的地（美国、西欧、日本、澳大利亚）',
  'te.br.intl.r.0.1': 'USD 403',
  'te.br.intl.r.0.2': '政府参考标准',
  'te.br.intl.r.1.0': 'B 组——中高成本目的地（中东、新加坡、加拿大、新西兰）',
  'te.br.intl.r.1.1': 'USD 352',
  'te.br.intl.r.1.2': '政府参考标准',
  'te.br.intl.r.2.0': 'C 组——中等成本目的地（东欧、拉丁美洲大部分地区、南非）',
  'te.br.intl.r.2.1': 'USD 298',
  'te.br.intl.r.2.2': '政府参考标准',
  'te.br.intl.r.3.0': 'D 组——较低成本目的地（南亚、撒哈拉以南非洲、中亚）',
  'te.br.intl.r.3.1': 'USD 244',
