  'te.cl.dom.r.3.0': '免税待遇（Art. 17 N°15）',
  'te.cl.dom.r.3.1': '金额合理且具备文件记录即可免税——无固定上限',
  'te.cl.dom.r.3.2': '法定',
  'te.cl.dom.r.4.0': '超过 SII“合理”标准的部分',
  'te.cl.dom.r.4.1': '作为雇佣所得征税（Second Category Tax）',
  'te.cl.dom.r.4.2': '法定',
  'te.cl.intl.title': '国际出差',
  'te.cl.intl.desc': '对于国际出差，智利同样未为私营部门规定强制性每日津贴标准。公共部门依据 Decreto 1.121（更新 DFL 262/77）制定的美元标准，通常作为免税待遇的参考基准。\n\n税务处理：同样适用 Art. 17 N°15 的免税规定——国际 viáticos 在金额合理且具备文件记录的情况下可免税。SII 会参考公共部门的美元标准作为私营部门的参考基准。\n\n公共部门参考标准（Decreto 1.121，金额以 USD/天计）：\n  • 北美 / 西欧：USD 315/天\n  • 日本 / 澳大利亚 / 新西兰：USD 290/天\n  • 亚太地区（不含日本）：USD 270/天\n  • 拉丁美洲：USD 230/天\n  • 非洲 / 东欧 / 中东：USD 210/天\n\n这些标准对私营部门并无法律约束力——应作为合理性参考指引。',
  'te.cl.intl.source': 'DFL N° 262/77 — public sector per diem scales; SII rulings on reasonableness',
  'te.cl.intl.h.0': '目的地区域',
  'te.cl.intl.h.1': '参考标准（USD/天）',
  'te.cl.intl.h.2': '来源类型',
  'te.cl.intl.r.0.0': '北美 / 西欧（美国、加拿大、英国、德国、法国等）',
  'te.cl.intl.r.0.1': 'USD 315',
  'te.cl.intl.r.0.2': '政府参考标准',
