  /* ── China (CN) ── */
  'te.cn.dom.title': '国内出差',
  'te.cn.dom.desc': '中国并未为私营部门雇主规定政府强制性的每日津贴标准。企业可自行制定差旅政策。\n\n根据个人所得税法（IIT Law）的税务处理规定：公务差旅费用报销不属于应税收入，但须符合以下条件：\n  1. 属于真实且有记录的公务出差\n  2. 具备有效发票（fapiao — 发票）或收据\n  3. 金额相对于实际支出属于合理范围\n\n如以固定现金津贴形式发放且无 fapiao 作为凭证，STA 可能将其认定为应税工资薪金所得，并按 IIT（3%–45%）征税。\n\nMOF 中央政府参考标准（2014 年 Circular，经修订）：\n  • 部级干部——住宿：北京/上海最高 CNY 1,100/晚\n  • 高级公务员（局级及以上）——住宿：最高 CNY 500–850/晚\n  • 普通公务员——住宿：最高 CNY 300–500/晚\n  • 餐费及杂费：通常 CNY 100–200/天（因城市等级而异）\n  • 城市按等级划分（一级城市：北京、上海、广州、深圳；二至四级城市：标准较低）\n\n注意：私营企业通常会参考政府标准作为基准。全国并无统一标准——实际适用应以企业自身政策为准。',
  'te.cn.dom.source': 'State Taxation Administration (STA) — IIT guidance on business travel reimbursements',
  'te.cn.dom.h.0': '类别',
  'te.cn.dom.h.1': '标准（CNY/天 — 中央政府参考）',
