  'te.cn.dom.r.8.2': '法定',
  'te.cn.intl.title': '国际出差',
  'te.cn.intl.desc': '对于国际出差，中国同样未为私营部门规定强制性的每日津贴标准。\n\n中央政府境外差旅规定（MOF regulations）：\n  • 每日津贴标准因国家而异，并以美元（USD）制定\n  • 住宿费用：凭实际收据按实际费用报销\n  • 商务舱：仅副部级及以上人员可乘坐\n\n私营部门：适用相同的 IIT 税务处理规定——凭 fapiao/收据报销实际境外差旅费用可免税；无凭证发放的固定现金津贴则需纳税。许多企业会参考美国国务院（U.S. State Department）或 UN ICSC 的标准作为国际差旅参考基准。\n\n外籍员工说明：公务差旅报销、住房补贴、餐费补贴及类似实物福利，在符合实际费用报销且具备有效 fapiao 的情况下，外籍员工可继续享受免税待遇至 2027 年底（已延长）。',
  'te.cn.intl.source': 'MOF Circular on Central Government Travel Expense Management (2014, as amended)',
  'te.cn.intl.h.0': '目的地',
