  'te.cn.intl.r.8.1': '凭实际费用及收据报销；如适用，提供 fapiao',
  'te.cn.intl.r.8.2': '市场惯例',
  'te.cn.intl.r.9.0': '税务处理 — 按实际费用报销境外差旅',
  'te.cn.intl.r.9.1': '本地员工及外籍员工均可免税至 2027 年',
  'te.cn.intl.r.9.2': '税务机关指引',

  /* ── Colombia (CO) ── */
  'te.co.dom.title': '国内出差',
  'te.co.dom.desc': '哥伦比亚并未为私营部门雇主规定政府强制性的每日津贴标准。企业可自行制定标准。Decreto 1083/2015 规定的公共部门标准被广泛用作参考基准。\n\n税务处理（Estatuto Tributario Art. 107）：\n  • 向员工支付的真实公务差旅津贴（viáticos），雇主可将其作为业务费用扣除\n  • 对员工而言：如 viáticos 用于实际公务差旅且金额合理，则不属于应税收入（Estatuto Tributario Art. 127）\n  • 如津贴金额过高或与真实差旅无关，DIAN 可能将其重新认定为工资收入，并按所得税税率（0%–39%）征税\n\n公共部门参考标准（Decreto 1083/2015——2025 年约数范围）：\n  • 主管 / 高级官员：COP 200,000–350,000/天\n  • 专业 / 技术级别：COP 120,000–200,000/天\n  • 支持人员：COP 70,000–120,000/天\n\n注意：COP 标准会随通货膨胀调整。2025 年 UVT = COP 49,799。应始终向 DIAN 或公司人力资源部门核实最新标准。',
  'te.co.dom.source': 'DIAN — Dirección de Impuestos y Aduanas Nacionales; Estatuto Tributario',
  'te.co.dom.h.0': '类别',
  'te.co.dom.h.1': '标准（COP/天——参考）',
  'te.co.dom.h.2': '来源类型',
  'te.co.dom.r.0.0': '公共部门——主管 / 高级官员',
  'te.co.dom.r.0.1': 'COP 200,000 – 350,000',
  'te.co.dom.r.0.2': '政府参考标准',
  'te.co.dom.r.1.0': '公共部门——专业 / 技术级别',
  'te.co.dom.r.1.1': 'COP 120,000 – 200,000',
  'te.co.dom.r.1.2': '政府参考标准',
  'te.co.dom.r.2.0': '公共部门——支持人员',
  'te.co.dom.r.2.1': 'COP 70,000 – 120,000',
  'te.co.dom.r.2.2': '政府参考标准',
  'te.co.dom.r.3.0': '私营部门',
  'te.co.dom.r.3.1': '依据公司政策（无法定标准）',
  'te.co.dom.r.3.2': '市场惯例',
  'te.co.dom.r.4.0': '税务处理（ET Art. 127）',
  'te.co.dom.r.4.1': '如用于真实公务差旅且金额合理，则不属于应税收入',
  'te.co.dom.r.4.2': '法定',
  'te.co.dom.r.5.0': '被认定为不合理或与差旅无关的金额',
  'te.co.dom.r.5.1': '作为应税工资收入征税（0%–39% IIT）',
  'te.co.dom.r.5.2': '法定',
  'te.co.intl.title': '国际出差',
  'te.co.intl.desc': '对于国际出差，哥伦比亚通常参考美国国务院每日津贴标准或类似基准。哥伦比亚政府并未针对私营部门国际差旅另行制定每日津贴标准表。\n\n公共部门：Decree 1083/2015 为出境公务差旅的政府官员制定美元标准，并根据目的地生活成本和员工职级划分不同等级。\n\n税务处理：同样适用 Estatuto Tributario Art. 127——如国际 viáticos 用于合法公务差旅且金额合理，则不属于应税收入。住宿费用通常须凭收据另行报销。\n\n私营部门参考标准（常见做法，依据公共部门指引）：\n  • 北美 / 西欧：USD 300–400/天\n  • 拉丁美洲：USD 200–300/天\n  • 亚太地区 / 中东：USD 250–350/天\n  • 非洲 / 东欧：USD 180–280/天',
  'te.co.intl.source': 'Public sector rates per Decreto 1083 of 2015 (Reglamento Único Sector Administrativo)',
  'te.co.intl.h.0': '目的地区域',
  'te.co.intl.h.1': '标准（USD/天——参考）',
