	/* ── South Korea (KR) ── */
	'te.kr.dom.title': '国内商务出差',
	'te.kr.dom.desc': '韩国没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定商务差旅费用政策。\n\n与商务差旅相关的韩国国税厅（NTS）主要免税规定：\n\n1. 餐费津贴（sik-dae, sik-dae）：\n   • 每月最高KRW 200,000免税（《所得税法》第12条）\n   • 仅适用于雇主未提供餐食的情况\n   • 自2023年1月起，由每月KRW 100,000提高至KRW 200,000\n\n2. 商务差旅费用规定（chul-jang-bi ）：\n   • 企业正式制定内部差旅费用规定\n   • 根据该规定支付的每日差旅津贴，视为非应税费用报销\n   • 金额必须合理，不得为避税而虚增\n   • 韩国国税厅可能将过高金额认定为应税收入\n\n政府参考标准（人事革新处）：\n   • 公务员国内每日差旅津贴按职级划分（附件1）\n   • 高级官员（1至3级）：每日杂费KRW 50,000–70,000\n   • 普通公务员（4至9级）：每日KRW 30,000–50,000\n\n私营部门常见参考标准（每日杂费 — 因公司及职级而异）：\n   • 高管级别：KRW 50,000–100,000/天\n   • 经理级别：KRW 30,000–70,000/天\n   • 普通员工级别：KRW 20,000–50,000/天\n\n2025年个人所得税：6%–45%累进税率（另按个人所得税税额加征10%的地方所得税）。\n外籍员工可选择在最长5年内适用19%的统一税率。\n2025年最低工资：KRW 10,030/小时（按209小时计算，每月约KRW 2,096,270）。',
	'te.kr.dom.source': '私营部门无法定每日差旅津贴标准。政府雇员适用人事革新处规定（按职级划分，附件1）。',
