	'te.kr.intl.title': '国际商务出差',
	'te.kr.intl.desc': '国际商务出差适用相同的韩国国税厅框架。根据公司正式制定的差旅规定支付的每日差旅津贴，视为非应税费用报销。\n\n政府参考标准（人事革新处 — 国际出差）：\n   • 公务员国际每日差旅津贴根据目的地国家设定\n   • 标准公布于《公务差旅费用规定》附件4\n   • 标准因职级和目的地而异\n\n私营部门常见国际参考标准（KRW/天杂费 — 住宿及交通另行报销）：\n   • 北美 / 西欧：KRW 80,000–200,000/天\n   • 日本 / 中国 / 东南亚：KRW 60,000–150,000/天\n   • 新兴市场 / 其他地区：KRW 40,000–100,000/天\n\n美国国务院针对前往韩国出差的2025年每日津贴标准：\n   • 首尔：住宿USD 213/晚 + 餐饮及杂费USD 100/天\n   • 韩国其他地区：住宿USD 130/晚 + 餐饮及杂费USD 71/天\n\n新加坡税务局2025年针对韩国的可接受标准：SGD 155/天',
	'te.kr.intl.source': '国际每日差旅津贴：适用相同框架 — 私营部门标准由类似旅费规定（Ryohi Kisoku）的公司差旅制度管理。',
	'te.kr.intl.h.0': '目的地 / 类别',
	'te.kr.intl.h.1': '标准 / 备注',
