	/* ── Spain (ES) ── */
	'te.es.dom.title': '国内商务出差 — 差旅津贴（Dietas）',
	'te.es.dom.desc': '西班牙税务局（AEAT）根据个人所得税（IRPF）法规规定了差旅津贴（dietas）的法定上限。该规定适用于所有私营部门雇主，且相关标准多年来一直未有调整。\n\n核心原则：必须前往通常工作地点所在市镇以外的地点出差。在同一市镇内出差不符合免税差旅津贴条件。\n\n国内差旅津贴上限（西班牙境内）：\n  • 餐费（manutención）：EUR 26.67/天免税\n  • 无酒店收据的住宿费：EUR 53.34/晚免税\n  • 有酒店收据的住宿费：实际费用免税（无上限）\n\n重要规则 — 餐券与差旅津贴：\n  • 员工不可在同一天同时申领餐券（vale comida / ticket restaurante）及差旅津贴 — 只能选择其中一种\n\n里程津贴：因公使用私家车可免税报销EUR 0.26/公里。\n\n税务处理：\n  • 不超过AEAT上限：完全免征个人所得税及社会保障缴费\n  • 超过上限：超出部分视为应税雇佣收入 — 须缴纳个人所得税（19%–47%累进税率）及社会保障缴费\n\n所需文件：\n  • 出差日期及目的地\n  • 商务目的\n  • 交通收据（航班、火车等）\n  • 如按实际住宿费用申报且金额高于定额标准，须提供酒店发票\n\n2025年个人所得税累进税率（国家税及地区税）：\n  • 不超过EUR 12,450：19% | EUR 12,451–20,200：24% | EUR 20,201–35,200：30%\n  • EUR 35,201–60,000：37% | EUR 60,001–300,000：45% | 超过EUR 300,000：47%',
	'te.es.dom.source': '西班牙税务局个人所得税手册第7.1.1.2节 — 餐费及住宿差旅津贴；相关标准多年来一直未调整',
	'te.es.dom.h.0': '类别',
	'te.es.dom.h.1': 'AEAT免税上限',
	'te.es.dom.h.2': '来源类型',
	'te.es.dom.r.0.0': '餐费（manutención）— 西班牙境内',
