	'te.es.dom.r.7.2': '法定规定',
	'te.es.intl.title': '国际商务出差',
	'te.es.intl.desc': '国际商务出差适用相同的AEAT框架，但为反映较高的海外生活成本，适用更高的免税上限。\n\n国际差旅津贴上限（西班牙境外）：\n  • 餐费（manutención）：EUR 48.08/天免税\n  • 无酒店收据的住宿费：EUR 91.35/晚免税\n  • 有酒店收据的住宿费：实际费用免税（无上限）\n\n适用相同条件：\n  • 必须前往通常工作地点所在市镇以外的地点\n  • 员工不可在同一天同时申领餐券及差旅津贴\n  • 必须提供适当文件\n\n注意：这些AEAT国际标准多年来一直未有调整。截至2026年年中，尚未公布即将修订的消息。应用前请始终通过sede.agenciatributaria.gob.es核实。\n\n美国国务院针对前往西班牙出差的2025年每日津贴标准：\n  • 马德里：住宿USD 237/晚 + 餐饮及杂费USD 107/天\n  • 巴塞罗那：住宿USD 233/晚 + 餐饮及杂费USD 105/天',
	'te.es.intl.source': '国际出差适用相同的个人所得税框架；无酒店账单时，每晚不超过EUR 91.35的住宿费无需提供收据',
