	'te.se.dom.r.10.2': '法定规定',
	'te.se.intl.title': '国际商务出差 — 2025年境外每日差旅津贴',
	'te.se.intl.desc': '针对国际出差，瑞典税务局每年根据各国标准餐厅餐费的生活成本调查，公布按国家划分的境外每日差旅津贴（utlandstraktamente）标准。\n\n规则：\n  • 如雇主提供免费餐食：早餐、午餐或晚餐每餐扣减15%\n  • 如同一天提供2餐或以上免费餐食：合计扣减35%\n  • 06:00–24:00期间停留时间最长的国家决定适用标准\n  • 在确定适用国家时，不计入乘坐飞机或船只在国家之间的旅行时间\n\n国际长期出差折减（在同一地点超过28天后）：\n  • 自第29天起：按该国家境外每日差旅津贴标准的75%计算\n\n部分2025年境外每日差旅津贴标准（SEK/天 — 瑞典税务局官方表格）：',
	'te.se.intl.source': '瑞典税务局 — 2025年境外每日差旅津贴：每年公布按国家划分的标准；根据餐厅成本调查进行审查',
