	'te.ch.intl.title': '国际商务出差',
	'te.ch.intl.desc': '国际商务出差适用相同的《债务法典》框架。瑞士没有法定每日差旅津贴标准 — 由公司自行设定标准。\n\n企业常用的实际做法：\n  1. 报销实际费用（提供住宿、餐饮及交通收据）\n  2. 根据获批准的费用规章支付定额每日差旅津贴\n  3. 参考外部标准（美国国务院、联合国国际公务员制度委员会、经合组织）\n\n未制定获批准费用规章的公司，应以ESTV参考上限作为基准，并记录所有超过该上限的金额。\n\n美国国务院针对前往瑞士出差的2025年每日津贴标准：\n  • 日内瓦：住宿USD 358/晚 + 餐饮及杂费USD 141/天\n  • 苏黎世：住宿USD 350/晚 + 餐饮及杂费USD 139/天\n  • 伯尔尼：住宿USD 282/晚 + 餐饮及杂费USD 117/天\n\n新加坡税务局2025年针对瑞士的可接受标准：SGD 170/天\n波兰2025年《条例》针对瑞士的标准：每日膳食津贴CHF 88\n\n注意：瑞士一直是商务出差成本最高的国家之一。对于大多数商务旅客而言，在苏黎世或日内瓦的实际全天住宿及餐饮费用通常超过CHF 400/天。',
	'te.ch.intl.source': '国际出差：适用相同的《债务法典》框架；无法定每日差旅津贴标准；公司自行设定金额，并取得联邦税务机关批准或参考相关基准',
