	/* ── Tanzania (TZ) ── */
	'te.tz.dom.title': '国内商务出差',
	'te.tz.dom.desc': '坦桑尼亚没有针对私营部门雇主的政府强制性每日差旅津贴标准。企业可自行制定差旅津贴政策。\n\n根据经修订的《2004年所得税法》的税务处理：\n  • 每月应税收入包括：基本工资、加班费、奖金、佣金、津贴及实物福利\n  • 因履行公务而真实发生并有适当文件证明的商务差旅费用报销，通常视为非应税费用报销\n  • 未提供文件证明或与实际差旅职责无关的固定现金津贴，可能被视为应税雇佣收入\n\n公务员政府参考标准（自2022年7月起生效 — 截至2025年仍适用）：\n  • 高级官员 / 主管：国内出差TZS 250,000/晚\n  • 较低级别公务员：国内出差TZS 100,000/晚\n  • 额外职务津贴（较低级别）：TZS 30,000/天\n  • 额外职务津贴（中级）：TZS 40,000/天\n  • 额外职务津贴（高级）：TZS 60,000/天\n\n2025年个人所得税税率（按月 — 《2004年所得税法》）：\n  • 每月不超过TZS 270,000：0%\n  • TZS 270,001–520,000：8%\n  • TZS 520,001–760,000：TZS 20,000 + 超过520,000部分的20%\n  • TZS 760,001–1,000,000：TZS 68,000 + 超过760,000部分的25%\n  • 超过TZS 1,000,000：TZS 128,000 + 超过1,000,000部分的30%\n  • 年度免税门槛：TZS 3,240,000/年\n\nNSSF缴费：合计20%（雇主10% + 员工10%）— 无缴费上限。\n技能发展税（SDL）：仅由雇主缴纳3.5%（适用于拥有10名或以上员工的机构）。\n最低工资（公共部门，2025年7月）：TZS 500,000/月。',
	'te.tz.dom.source': '私营部门：无法定每日差旅津贴标准。根据《2004年所得税法》，真实且有文件证明的差旅费用报销通常免税。',
