	'te.th.dom.r.5.0': '国际商务中心制度员工（特殊）',
	'te.th.dom.r.5.1': '符合条件的国际商务中心活动所产生的雇佣收入统一适用15%的个人所得税税率',
	'te.th.dom.r.5.2': '法定规定',
