	'te.th.dom.r.6.1': '0%–35%累进税率：不超过THB 150K免税；超过部分适用5%–35%',
	'te.th.dom.r.6.2': '法定规定',
	'te.th.intl.title': '国际商务出差',
	'te.th.intl.desc': '国际商务出差适用相同的《税收法典》第42(1)条框架。完全且必要地用于履行工作职责的每日差旅津贴不属于应税收入。\n\n政府并未针对私营部门公布统一的国际差旅津贴标准表。\n\n美国国务院针对前往泰国出差的2025年每日津贴标准：\n  • 曼谷：住宿USD 165/晚 + 餐饮及杂费USD 75/天\n  • 泰国其他地区（清迈、普吉岛）：标准较低 — 请通过美国国务院核实\n\n新加坡税务局2025年针对泰国的可接受标准：SGD 110/天\n\n泰国员工出境出差的私营部门参考标准：\n  • 美国 / 西欧：USD 250–380/天\n  • 日本 / 新加坡 / 澳大利亚：USD 200–300/天\n  • 亚洲区域内（中国、东盟）：USD 150–250/天\n\n注意：泰国于2022年推出新的长期居留签证（LTR）计划及国际商务中心（IBC）税务制度。IBC制度下的员工可能适用较低的15%统一所得税税率。',
	'te.th.intl.source': '国际出差：适用相同框架 — 完全且必要发生的每日差旅津贴免税；由公司自行设定国际差旅标准',
