	'te.tr.intl.title': '国际商务出差 — 境外差旅津贴（Harcırah）',
	'te.tr.intl.desc': '针对国际商务出差，土耳其通过每半年在《官方公报》公布的总统决定，发布按国家划分的差旅津贴标准。\n\n国际差旅津贴标准 — 2025年1月至6月：\n  • 对于每月税前工资高于TRY 35,907.57的员工：\n    按国家分别适用以USD或EUR计价的标准 — 适用相同上限原则\n    来源：2025年1月11日第32779号《官方公报》公布的第9396号总统决定\n\n  • 对于每月税前工资低于TRY 35,907.57的员工：\n    根据其工资档次按比例适用较低标准\n\n税务处理：\n  • 不超过已公布的国家特定上限：无需缴纳个人所得税或社会保障缴费\n  • 超过已公布上限的金额：视为应税工资收入\n\n部分参考标准（2025年1月至6月 — 适用于每月税前工资高于TRY 35,907.57的较高工资档次 — USD或EUR/天）：\n注意：以下为最高免税金额。请始终通过gib.gov.tr或《官方公报》核实当前半年度更新。\n\n美国国务院针对前往土耳其出差的2025年每日津贴标准：\n  • 伊斯坦布尔：住宿USD 180/晚 + 餐饮及杂费USD 89/天\n  • 安卡拉：住宿USD 158/晚 + 餐饮及杂费USD 81/天',
	'te.tr.intl.source': '国际差旅津贴：适用于每月税前工资高于TRY 35,907.57的工资档次；各国家分别适用不同的USD/EUR金额（2025年1月11日第32779号《官方公报》）',
