	/* ── Ukraine (UA) ── */
	'te.ua.dom.title': '国内商务出差 — 每日差旅津贴（Dobovi）',
	'te.ua.dom.desc': '乌克兰根据《税法典》第170.9条规定了法定每日差旅津贴（dobovi）上限。该上限为员工商务出差可享受的最高免税金额。\n\n国内每日差旅津贴（dobovi）— 自2025年1月1日起：\n  • 最高UAH 800/天（免税）\n  • 按每日最低工资的0.1倍计算\n  • 自2025年1月1日起的最低工资：UAH 8,000/月\n  • 因此：0.1 x UAH 8,000 = UAH 800/天\n\n税务处理：\n  • 不超过UAH 800/天：无需缴纳个人所得税（18%）、军事税（5%）或统一社会缴费（USC，雇主22%）\n  • 超过UAH 800/天：超出部分属于应税收入 — 须缴纳18%的个人所得税及5%的军事税，即超出部分的实际综合税率为23%\n\n重要背景 — 戒严状态：\n  • 乌克兰自2022年2月起一直处于戒严状态\n  • 根据第4015-IX号法律，军事税自2024年12月1日起由1.5%提高至5%\n  • 军事税适用于个人的所有应税收入\n  • 超过法定上限的每日差旅津贴须同时缴纳个人所得税（18%）及军事税（5%）\n\n个人所得税税率：雇佣收入统一适用18%。军事税：5%（自2024年12月起）。\n最低工资：UAH 8,000/月（2025年1月）。UAH汇率：USD 1 ≈ UAH 41–42（2025年）。',
	'te.ua.dom.source': 'Forvis Mazars乌克兰：自2025年1月1日起，国内每日差旅津贴为UAH 800/天（最低工资的0.1倍）。国际每日差旅津贴为每个日历日EUR 80（保持不变）。',
	'te.ua.dom.h.0': '类别',
	'te.ua.dom.h.1': '标准 / 税务处理',
	'te.ua.dom.h.2': '来源类型',
	'te.ua.dom.r.0.0': '国内每日差旅津贴（dobovi）— 自2025年1月1日起',
	'te.ua.dom.r.0.1': 'UAH 800/天（UAH 8,000最低工资的0.1倍）— 免税上限',
	'te.ua.dom.r.0.2': '法定规定',
	'te.ua.dom.r.1.0': '不超过UAH 800/天的金额',
	'te.ua.dom.r.1.1': '无需缴纳个人所得税（18%）、军事税（5%）或统一社会缴费',
	'te.ua.dom.r.1.2': '法定规定',
	'te.ua.dom.r.2.0': '超过UAH 800/天的金额',
	'te.ua.dom.r.2.1': '属于应税收入 — 超出部分须缴纳18%的个人所得税及5%的军事税',
	'te.ua.dom.r.2.2': '法定规定',
	'te.ua.dom.r.3.0': '军事税税率（自2024年12月1日起 — 第4015-IX号法律）',
	'te.ua.dom.r.3.1': '所有应税收入适用5%税率（由1.5%提高）',
	'te.ua.dom.r.3.2': '法定规定',
	'te.ua.dom.r.4.0': '个人所得税税率',
	'te.ua.dom.r.4.1': '扣除后雇佣收入统一适用18%税率',
	'te.ua.dom.r.4.2': '法定规定',
	'te.ua.dom.r.5.0': '最低工资（2025年1月）',
	'te.ua.dom.r.5.1': 'UAH 8,000/月（每日差旅津贴上限按该金额的0.1倍确定）',
	'te.ua.dom.r.5.2': '法定规定',
	'te.ua.intl.title': '国际商务出差',
	'te.ua.intl.desc': '针对国际商务出差，乌克兰根据《税法典》第170.9条规定了以欧元计价的固定免税每日差旅津贴上限。\n\n国际每日差旅津贴（dobovi）上限：\n  • 每个日历日最高EUR 80（免税）\n  • 按乌克兰国家银行（NBU）每日公布的官方汇率折算为UAH\n  • 尽管国内标准有所提高，该上限仍保持不变\n\n税务处理：\n  • 不超过EUR 80/天：无需缴纳个人所得税（18%）或军事税（5%）\n  • 超过EUR 80/天：须缴纳18%的个人所得税及5%的军事税\n\n文件要求：\n  • 必须提供出差命令（nakazatel pro komandiruvannya）\n  • 返回后提交费用报告\n  • 提供住宿及交通收据\n\n美国国务院针对前往乌克兰出差的2025年每日津贴标准：\n  • 基辅：住宿USD 150/晚 + 餐饮及杂费USD 78/天\n  • 注意：鉴于出行安全状况，请查阅您所在国家政府发布的旅行建议\n\n新加坡税务局2025年针对乌克兰的可接受标准：SGD 110/天',
	'te.ua.intl.source': '军事税：根据第4015-IX号法律，自2024年12月1日起由1.5%提高至5% — 适用于须缴纳个人所得税的收入，包括超出上限的每日差旅津贴',
	'te.ua.intl.h.0': '目的地 / 类别',
