	/* ── Uzbekistan (UZ) ── */
	'te.uz.dom.title': '国内商务出差',
	'te.uz.dom.desc': '乌兹别克斯坦根据《税法典》及内阁决议规定了法定每日差旅津贴（komandirovochnye / sutochnie）标准。法定标准范围内的每日差旅津贴无需缴纳个人所得税（PIT）。\n\n根据乌兹别克斯坦《税法典》的税务处理：\n  • 法定标准范围内的每日差旅津贴及差旅费用报销：不计入应税雇佣收入\n  • 超出法定标准的每日差旅津贴：视为应税雇佣收入 — 须缴纳12%的统一个人所得税及社会税\n\n法定标准：\n  • 国内出差：每日最高为基础计算值（BCV）的2倍\n  • 2025年基础计算值（BCV，Bazovaya Raschetnaya Velichina）：UZS 375,000\n  • 因此，国内每日上限：2 x UZS 375,000 = UZS 750,000/天\n  • 注意：基础计算值会根据政府法令更新 — 请通过soliq.uz核实\n\n住宿：根据实际发生且有收据证明的费用另行报销。\n交通：凭相关证明文件按实际费用报销。\n\n2025年所得税：所有雇佣收入统一适用12%的个人所得税税率（自2023年1月起实施）。\n社会税（雇主）：按税前工资总额的12%缴纳。\n养老金缴费（员工）：按税前工资总额的1%缴纳。\n最低工资：每月UZS 1,200,000（截至2025年8月）。\nUZS汇率：USD 1 ≈ UZS 12,700–12,900（2025年）。',
	'te.uz.dom.source': '法定标准范围内的每日差旅津贴：免税。超出法定标准的每日差旅津贴：视为应税雇佣收入（普华永道乌兹别克斯坦收入认定指引）。统一个人所得税税率：12%。',
	'te.uz.dom.h.0': '类别',
	'te.uz.dom.h.1': '标准 / 税务处理',
	'te.uz.dom.h.2': '来源类型',
	'te.uz.dom.r.0.0': '法定标准范围内的国内每日差旅津贴',
	'te.uz.dom.r.0.1': '每日最高为BCV的2倍 = UZS 750,000/天（2025年BCV = UZS 375,000 — 请每年核实）',
	'te.uz.dom.r.0.2': '法定规定',
