	/* ── Vietnam (VN) ── */
	'te.vn.dom.title': '国内商务出差 — 差旅费（Cong Tac Phi）',
	'te.vn.dom.desc': '越南并未针对私营部门雇主规定政府强制性的每日差旅津贴标准。企业可自行制定差旅津贴政策。\n\n根据《个人所得税法》及第111/2013/TT-BTC号通知的税务处理：\n  • 完全、专门且必要地用于履行工作职责的每日差旅津贴（cong tac phi）及差旅费用，不属于应税收入\n  • 这意味着该等款项无需缴纳个人所得税（PIT）\n  • 相关费用必须真实发生、用于业务目的，并有适当文件作为证明\n\n其他相关免税津贴（适用特定上限）：\n  • 午餐津贴：每日VND 730,000为此前的参考标准（根据现行指引，企业可自行设定合理金额）\n  • 制服津贴：如以现金支付，每年最高VND 5,000,000；如以实物形式提供，则不设上限\n  • 电话津贴：以公司政策规定的限额为准\n\n2025年个人所得税税率（税务居民 — 5%–35%累进税率）：\n  • 每月不超过VND 60M：5% | VND 60M–120M：10% | VND 120M–216M：15%\n  • VND 216M–384M：20% | VND 384M–624M：25% | VND 624M–960M：30%\n  • 每月超过VND 960M：35%\n\n重要 — 2025年个人所得税法改革：\n  • 国民议会已通过修正案，将个人扣除额由每月VND 11M提高至VND 15.5M\n  • 个人所得税税级由7级减少至5级，并调整适用门槛\n  • 请通过gdt.gov.vn核实生效日期及实施法令\n\n最低工资（第一区 — 胡志明市，自2024年7月1日起）：每月VND 4,960,000。',
	'te.vn.dom.source': '完全且必要地用于履行工作职责的差旅费用（cong tac phi）不属于应税收入。依据经更新的第111/2013/TT-BTC号通知。',
